={
  "name": "{{
(() => {
  let name = $('GET PERSON').item.json.data[0]?.name || '';
  const doctor = $('webhook data').item.json.data[0]?.nombre_doctor || '';

  // 🔥 limpiar guiones basura tipo " - - - "
  name = name.replace(/(\s*-\s*)+/g, ' - ').trim();

  // 🔥 si no hay doctor, devolver nombre limpio
  if (!doctor || doctor.trim() === '') {
    return name.replace(/\s*-\s*$/, '').trim(); // quita guion final si queda colgando
  }

  const parts = name.split('-');
  const baseName = parts[0].trim();
  const afterDash = parts[1]?.trim();

  // 🔥 si ya existe doctor, no duplicar
  if (afterDash && afterDash.includes(doctor)) {
    return `${baseName} - ${afterDash}`;
  }

  // 🔥 si ya hay algo después del "-", agregar sin duplicar
  if (afterDash) {
    return `${baseName} - ${afterDash} ${doctor}`;
  }

  // 🔥 caso normal
  return `${baseName} - ${doctor}`;
})()
}}",
  "emails": [
    {
      "label": "work",
      "value": "{{ $('GET PERSON').item.json.data[0].emails[0].value }}"
    }
  ],
